function validate([parents, queries]) {
  const n = parents.length;
  if (n < 2 || n > 100000) return 'parents needs 2 to 100000 entries.';
  if (parents.filter(p => p === -1).length !== 1) return 'Exactly one node must be the root (parent -1).';
  if (parents.some((p, i) => p !== -1 && (!Number.isInteger(p) || p < 0 || p >= n || p === i))) return 'Each parent must be another node from 0 to n - 1, or -1 for the root.';
  // Every node must reach the root without running into a cycle.
  const state = new Array(n).fill(0);
  for (let start = 0; start < n; start++) {
    const path = [];
    let node = start;
    while (node !== -1 && state[node] === 0) {
      state[node] = 1;
      path.push(node);
      node = parents[node];
    }
    if (node !== -1 && state[node] === 1) return 'parents must form a tree: following parents from a node loops back on itself.';
    for (const visited of path) state[visited] = 2;
  }
  if (queries.length < 1 || queries.length > 30000) return 'queries needs 1 to 30000 entries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is a pair [node, val].';
    const [node, val] = query;
    if (!Number.isInteger(node) || node < 0 || node >= n) return 'Each queried node must be from 0 to n - 1.';
    if (!Number.isInteger(val) || val < 0 || val > 200000) return 'Each val must be from 0 to 200000.';
  }
  return null;
}

