function maxGeneticDifference(parents, queries) {
  const n = parents.length;
  const HIGH_BIT = 17;
  const children = parents.map(() => []);
  let root = 0;
  for (let node = 0; node < n; node++) {
    if (parents[node] === -1) root = node;
    else children[parents[node]].push(node);
  }
  const asked = parents.map(() => []);
  queries.forEach(([node], index) => asked[node].push(index));
  const trie = [[0, 0]];
  const count = [0];
  const update = (value, delta) => {
    let at = 0;
    for (let bit = HIGH_BIT; bit >= 0; bit--) {
      const side = (value >> bit) & 1;
      if (trie[at][side] === 0) {
        trie[at][side] = trie.length;
        trie.push([0, 0]);
        count.push(0);
      }
      at = trie[at][side];
      count[at] += delta;
    }
  };
  const best = (value) => {
    let at = 0;
    let result = 0;
    for (let bit = HIGH_BIT; bit >= 0; bit--) {
      const want = ((value >> bit) & 1) ^ 1;
      const next = trie[at][want];
      if (next !== 0 && count[next] > 0) {
        result |= 1 << bit;
        at = next;
      } else {
        at = trie[at][want ^ 1];
      }
    }
    return result;
  };
  const answer = new Array(queries.length).fill(0);
  const stack = [[root, false]];
  while (stack.length > 0) {
    const [node, leaving] = stack.pop();
    if (leaving) {
      update(node, -1);
      continue;
    }
    update(node, 1);
    for (const index of asked[node]) {
      answer[index] = best(queries[index][1]);
    }
    stack.push([node, true]);
    for (const child of children[node]) {
      stack.push([child, false]);
    }
  }
  return answer;
}

