function maxGeneticDifference(parents, queries) {
  // Climb from each queried node to the root and try every value on the way.
  return queries.map(([node, val]) => {
    let most = 0;
    for (let p = node; p !== -1; p = parents[p]) most = Math.max(most, val ^ p);
    return most;
  });
}

