function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 2 + Math.floor(rand() * 7);
  const q = large ? 2000 : 1 + Math.floor(rand() * 6);
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  // Shuffled labels; a "chainy" tree hangs each node near the previous one, so it gets deep.
  const parents = new Array(n);
  parents[order[0]] = -1;
  const chainy = rand() < 0.4;
  for (let i = 1; i < n; i++) {
    const pick = chainy ? Math.max(0, i - 1 - Math.floor(rand() * 3)) : Math.floor(rand() * i);
    parents[order[i]] = order[pick];
  }
  const maxVal = large || rand() < 0.3 ? 200000 : 31;
  const queries = Array.from({ length: q }, () => [Math.floor(rand() * n), Math.floor(rand() * (maxVal + 1))]);
  return [parents, queries];
}
